-- CRM Seeder
-- ================================================================
-- Demo data for the crm (sales pipeline / revenue operations)
-- module. Apply supabase/examples/20260801000000_crm.sql first:
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 \
--     -f supabase/examples/20260801000000_crm.sql \
--     -f supabase/examples/c_seed.sql
--
-- Volume: 8 territories (three levels deep), 12 sales reps in an org
-- chart, 6 compensation records, 10 products, 6 campaigns, 30
-- accounts, 73 contacts and 34 leads — three of which are converted
-- through crm.convert_lead(), which mints another 3 accounts, 3
-- contacts and 3 deals. On top of that: 63 opportunities spanning
-- fourteen months, 101 line items, 134 buying-committee links, 40
-- quotes, 184 logged activities and 40 tasks. The triggers derive
-- another 539 deal-history events from all of it.
--
-- Dates are all relative to `current_date` / `current_timestamp`, so
-- the dashboards, the 14-day flow chart, the forecast area chart,
-- the gantt roadmaps and the monthly bookings rollup all have shape
-- whenever this is run.
--
-- WHY THIS FILE IS NOT JUST A PILE OF INSERTS
--
-- A CRM only looks real if its deals have been *lived*. Inserting a
-- row that is already `closed_won` produces one "created" event, a
-- days_in_stage of zero and no history at all — the timeline tab,
-- the stalled-deal widget and the win/loss report would all be
-- empty or wrong.
--
-- So the deals here are inserted at `qualification` and then walked
-- forward in cohorts, one stage at a time, exactly as a sales floor
-- would move them. That produces the real stage_changed /
-- closed_won / closed_lost history, and it exercises every guard in
-- the module on the way through. Three later passes then age the
-- result: stage clocks are pushed back so some deals read as
-- stalled, and the generated events are moved onto the dates they
-- describe so the feed is a history rather than one timestamp.
--
-- Everything derived is left to the module: probability and
-- forecast category from the stage, weighted_amount from the
-- probability, amount from the line items, account and campaign
-- rollups, last_activity_at, lead auto-assignment, task overdue
-- flags and every opportunity_events row.
--
-- Five hardcoded users are seeded first so this file can run
-- independently of supabase/seed.sql (`on conflict do nothing`, so
-- it is also safe to run after supabase/seed.sql has created the
-- first three):
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b8  superadmin@supasheet.app (x-admin)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b5  manager@supasheet.app    (manager)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b6  rep@supasheet.app        (rep)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b1  user1@supasheet.app      (user)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b4  user@supasheet.app       (user)
--
-- Sign in as manager@supasheet.app to run the floor (whole pipeline,
-- forecast, roster — but no compensation), as rep@supasheet.app to
-- see an account executive's seat (Sam Okoye: reads the pipeline,
-- edits only what he owns, sees only his own leads and tasks, and is
-- blocked from editing a closed deal), and as user@supasheet.app for
-- the read-only seat (accounts, contacts and interaction history, no
-- pipeline at all).
--
-- Password for every seeded user: the shared bcrypt hash below,
-- matching the rest of the Supasheet examples.
--
-- Not idempotent beyond the auth rows: re-running inserts duplicate
-- primary keys. Run `npx supabase db reset` to start over.
-- ================================================================
----------------------------------------------------------------
-- Users
----------------------------------------------------------------
