-- Territory managers: the circular reference the schema file adds
-- the column for.
update crm.territories
set
  manager_id = case code
    when 'GLOBAL' then 'c3000000-0000-0000-0000-000000000001'::uuid
    when 'EMEA' then 'c3000000-0000-0000-0000-000000000002'::uuid
    when 'AMER' then 'c3000000-0000-0000-0000-000000000003'::uuid
    when 'APAC' then 'c3000000-0000-0000-0000-00000000000a'::uuid
    when 'UKI' then 'c3000000-0000-0000-0000-000000000004'::uuid
    when 'DACH' then 'c3000000-0000-0000-0000-000000000005'::uuid
    when 'NA' then 'c3000000-0000-0000-0000-000000000007'::uuid
    when 'LATAM' then 'c3000000-0000-0000-0000-000000000008'::uuid
  end;

