----------------------------------------------------------------
-- Contacts
--
-- first_name and last_name are what the form asks for;
-- crm.trg_contacts_apply_defaults derives the `name` column every
-- join, lookup and display column points at. One primary contact per
-- account is enforced by a partial unique index.
