----------------------------------------------------------------
-- Leads
--
-- Three of these have no owner on purpose. Watch what happens:
-- crm.trg_leads_apply_defaults hands every unowned lead to the
-- least-loaded rep who is taking work in that territory, so they
-- come out of this INSERT already routed. The three converted ones
-- further down go through crm.convert_lead() rather than being
-- hand-written, which is what creates their account, contact and
-- opportunity.
----------------------------------------------------------------
insert into
  crm.leads (
    id,
    first_name,
    last_name,
    company,
    job_title,
    email,
    phone,
    website,
    status,
    rating,
    source,
    score,
    owner_id,
    campaign_id,
    territory_id,
    industry,
    employee_count,
    estimated_value,
    country,
    notes,
    disqualified_reason,
    last_contacted_at,
    tags,
    user_id,
    created_at
  )
