-- Convert the three strongest qualified leads through the real
-- action, so each one produces an account, a contact and a
-- qualification-stage opportunity exactly as the UI button would.
select
  crm.convert_lead ('c7000000-0000-0000-0000-000000000001');

select
  crm.convert_lead ('c7000000-0000-0000-0000-00000000000b');

select
  crm.convert_lead ('c7000000-0000-0000-0000-000000000020');

----------------------------------------------------------------
-- Opportunities
--
-- Every deal is inserted at `qualification` with amount 0. The line
-- items below set the real amount through
-- crm.trg_line_items_rollup, and the pipeline walk further down
-- moves each deal to where it actually ended up — which is what
-- produces the stage history, the closure records and the cycle
-- lengths the win/loss report reads.
----------------------------------------------------------------
