  crm.opportunities (
    id,
    name,
    account_id,
    primary_contact_id,
    owner_id,
    territory_id,
    campaign_id,
    source,
    opportunity_type,
    opened_on,
    expected_close_on,
    is_key_deal,
    next_step,
    user_id,
    created_at
  )
