----------------------------------------------------------------
-- Line items
--
-- unit_price, billing_frequency and term_months are left out: they
-- are exactly what the product lookup fills in the UI, so the seed
-- copies them off crm.products the same way. crm.trg_line_items_*
-- then prices each line and rolls the total up onto the deal.
----------------------------------------------------------------
insert into
  crm.opportunity_line_items (
    id,
    opportunity_id,
    product_id,
    quantity,
    unit_price,
    discount_percent,
    billing_frequency,
    term_months,
    sort_order
  )
select
  v.id,
  v.opportunity_id,
  v.product_id,
  v.quantity,
  p.list_price,
  case
    when a.tier in ('strategic', 'enterprise') then 10
    when v.sort_order = 1
    and o.is_key_deal then 5
    else 0
  end,
  p.billing_frequency,
  p.minimum_term_months,
  v.sort_order
from
  (
    values
      (
        'c9000000-0000-0000-0000-000000000001'::uuid,
        'c8000000-0000-0000-0000-000000000001'::uuid,
        'c5000000-0000-0000-0000-000000000003'::uuid,
        2,
        1
      ),
      (
        'c9000000-0000-0000-0000-000000000002'::uuid,
        'c8000000-0000-0000-0000-000000000001'::uuid,
        'c5000000-0000-0000-0000-000000000007'::uuid,
        1,
        2
      ),
      (
        'c9000000-0000-0000-0000-000000000003'::uuid,
        'c8000000-0000-0000-0000-000000000001'::uuid,
        'c5000000-0000-0000-0000-000000000009'::uuid,
        1,
        3
      ),
      (
        'c9000000-0000-0000-0000-000000000004'::uuid,
        'c8000000-0000-0000-0000-000000000002'::uuid,
        'c5000000-0000-0000-0000-000000000003'::uuid,
        2,
        1
      ),
      (
        'c9000000-0000-0000-0000-000000000005'::uuid,
        'c8000000-0000-0000-0000-000000000002'::uuid,
        'c5000000-0000-0000-0000-000000000007'::uuid,
        1,
        2
      ),
