-- would move them. Each statement fires
-- crm.trg_opportunities_apply_defaults (probability, forecast
-- category, stage clock) and crm.trg_opportunities_log_event (the
-- history), so the deals arrive at their final stage having actually
-- been there.
----------------------------------------------------------------
