----------------------------------------------------------------
-- Age the stage clocks
--
-- The walk above just moved every open deal, so each one currently
-- reads as "0 days in stage" and nothing looks stalled. Pushing
-- stage_changed_at back into the past is enough: the BEFORE trigger
-- recomputes days_in_stage from it on the same statement, which is
-- what the "Stalled 30d+" preset and the stalled-deals widget filter
-- on.
----------------------------------------------------------------
update crm.opportunities o
set
  stage_changed_at = v.moved_at
from
  (
    values
      (
        'c8000000-0000-0000-0000-000000000025'::uuid,
        current_timestamp - interval '40 days'
      ),
      (
        'c8000000-0000-0000-0000-000000000026'::uuid,
        current_timestamp - interval '47 days'
      ),
