----------------------------------------------------------------
-- Slip a few close dates
--
-- Deals slip. Three open ones are pulled back to a close date that
-- has already passed, which is both realistic and what keeps the
-- "Closing This Month" widget honest on any day of the month --
-- including the last one, when everything still in the future
-- belongs to next month already.
----------------------------------------------------------------
update crm.opportunities
set
  expected_close_on = current_date - 4
where
  id = 'c8000000-0000-0000-0000-000000000027';

update crm.opportunities
set
  expected_close_on = current_date - 11
where
  id = 'c8000000-0000-0000-0000-00000000002d';

update crm.opportunities
set
  expected_close_on = current_date - 2
where
  id = 'c8000000-0000-0000-0000-000000000031';

----------------------------------------------------------------
-- Quotes
--
-- Inserted as drafts, then moved to their real status one statement
-- at a time so crm.trg_quotes_apply_defaults stamps sent_at /
-- accepted_at and crm.trg_quotes_log_event files the quote entry on
-- the deal timeline. subtotal is copied off the deal amount; the
-- trigger computes `total` from the parts.
----------------------------------------------------------------
insert into
  crm.quotes (
    id,
    opportunity_id,
    account_id,
    owner_id,
    subtotal,
    discount_amount,
    tax_amount,
    currency,
    valid_until,
    terms,
    created_at
  )
select
  v.id,
  o.id,
  o.account_id,
  o.owner_id,
  o.amount,
  round(o.amount * v.extra_discount / 100, 2),
  0,
  o.currency,
  v.valid_until,
  'Prices in ' || o.currency || '. Valid until the date shown above. Net 30 on countersignature.',
  v.created_at
from
  (
    values
      (
        'cb000000-0000-0000-0000-000000000001'::uuid,
        'c8000000-0000-0000-0000-000000000001'::uuid,
        3,
        current_date - 390,
        current_timestamp - interval '420 days'
      ),
      (
        'cb000000-0000-0000-0000-000000000002'::uuid,
        'c8000000-0000-0000-0000-000000000002'::uuid,
        5,
        current_date - 355,
        current_timestamp - interval '385 days'
