----------------------------------------------------------------
-- Age the quote stamps
--
-- crm.trg_quotes_apply_defaults stamped sent_at and accepted_at with
-- current_timestamp as each quote moved, which would put every quote
-- entry on the deal timeline *after* the deal closed. Pull them back
-- onto the deal's own clock: sent a couple of days after the quote
-- was raised, accepted a couple of days before the deal closed.
--
-- The trigger only stamps on a status *change*, so rewriting the
-- timestamps here leaves them alone.
----------------------------------------------------------------
update crm.quotes q
set
  sent_at = date_trunc('day', q.created_at) + interval '2 days 9 hours',
  accepted_at = case
    when q.status = 'accepted' then date_trunc(
      'day',
      coalesce(
        o.actual_close_on::timestamptz - interval '2 days',
        q.created_at + interval '9 days'
      )
    ) + interval '15 hours'
    else null
  end
from
  crm.opportunities o
where
  o.id = q.opportunity_id
  and q.status <> 'draft';

----------------------------------------------------------------
-- Activities
--
-- The interaction history behind every deal. crm.trg_activities_after
-- stamps last_activity_at on the account, the deal and the contact,
-- and files an "activity_logged" entry on the deal timeline — which
-- is why these are inserted with an explicit occurred_at rather than
-- being backdated afterwards.
----------------------------------------------------------------
insert into
  crm.activities (
    id,
    activity_type,
    subject,
    notes,
    account_id,
    contact_id,
    opportunity_id,
    owner_id,
    direction,
    outcome,
    occurred_at,
    duration,
    location,
    follow_up_on,
    user_id
  )
