-- Tasks
--
-- A mix of open, overdue, completed and cancelled so the task board,
-- the calendar and the overdue widget all have something to show.
-- crm.trg_tasks_apply_defaults stamps completed_at and raises the
-- is_overdue flag; nothing here sets either by hand.
----------------------------------------------------------------
