    current_timestamp + interval '4 days',
    null,
    'b73eb03e-fb7a-424d-84ff-18e2791ce0b8',
    current_timestamp - interval '43 days'
  ),
  (
    'cd000000-0000-0000-0000-000000000027',
    'Schedule the onboarding kick-off',
    'Hand over to the CSM with the account plan.',
    'not_started',
    'low',
    'c3000000-0000-0000-0000-000000000005',
    'c2000000-0000-0000-0000-000000000008',
    'c8000000-0000-0000-0000-000000000035',
    'c4000000-0000-0000-0000-000000000013',
    current_date - 7,
    current_timestamp + interval '5 days',
    null,
    'b73eb03e-fb7a-424d-84ff-18e2791ce0b8',
    current_timestamp - interval '44 days'
  ),
  (
    'cd000000-0000-0000-0000-000000000028',
    'Send the security questionnaire back',
    'The customer needs the completed pack before the review board meets.',
    'in_progress',
    'normal',
    'c3000000-0000-0000-0000-000000000006',
    'c2000000-0000-0000-0000-00000000000b',
    'c8000000-0000-0000-0000-000000000036',
    'c4000000-0000-0000-0000-000000000019',
    current_date + 6,
    current_timestamp + interval '1 days',
    null,
    'b73eb03e-fb7a-424d-84ff-18e2791ce0b8',
    current_timestamp - interval '45 days'
  );

----------------------------------------------------------------
-- Age the deal history
--
-- Every event above was filed by a trigger during this seed run, so
-- they all carry the same timestamp and the timeline tabs read as
-- one block. Each event is now moved onto the moment it describes:
-- creation to the deal's created_at, closure to its close date,
-- activity and quote entries to the row they came from, and the
-- intermediate stage movements spread evenly across the deal's life
-- so the sequence reads as a real cycle.
--
-- actor_id gets the same treatment. In the app the column default
-- auth.uid() captures whoever made the change; a seed file has no
-- session, so events are attributed to the owning rep where that rep
-- has a login, and to the account that filed the deal otherwise.
----------------------------------------------------------------
update crm.opportunity_events e
set
  occurred_at = o.created_at
from
  crm.opportunities o
where
  o.id = e.opportunity_id
  and e.event_type = 'created';

update crm.opportunity_events e
set
  occurred_at = o.actual_close_on::timestamptz + interval '16 hours'
from
  crm.opportunities o
where
  o.id = e.opportunity_id
  and e.event_type in ('closed_won', 'closed_lost')
  and o.actual_close_on is not null;

update crm.opportunity_events e
set
  occurred_at = a.occurred_at
from
  crm.activities a
where
  e.event_type = 'activity_logged'
  and (e.metadata ->> 'activity_id')::uuid = a.id;

-- A quote files one event per status it passed through, so the
-- event's own metadata decides which of the quote's timestamps it
-- belongs on.
update crm.opportunity_events e
set
  occurred_at = case e.metadata ->> 'status'
    when 'accepted' then coalesce(q.accepted_at, q.sent_at, q.created_at)
    when 'declined' then coalesce(q.sent_at, q.created_at) + interval '4 days'
    else coalesce(q.sent_at, q.created_at)
  end
from
  crm.quotes q
where
  e.event_type = 'quote_sent'
  and (e.metadata ->> 'quote_id')::uuid = q.id;

-- The intermediate movements: spread evenly between the day the deal
-- was opened and the day it closed (or today, if it is still open).
with
  spread as (
    select
      e.id,
      o.created_at as started,
      coalesce(
        o.actual_close_on::timestamptz + interval '14 hours',
        current_timestamp
      ) as ended,
      row_number() over (
        partition by
          e.opportunity_id
        order by
          e.occurred_at,
          e.id
      ) as seq,
      count(*) over (
        partition by
          e.opportunity_id
      ) as total
    from
      crm.opportunity_events e
      join crm.opportunities o on o.id = e.opportunity_id
    where
      e.event_type in (
        'stage_changed',
        'amount_changed',
        'owner_changed',
        'reopened',
        'record_updated'
      )
  )
update crm.opportunity_events e
set
  occurred_at = spread.started + (spread.ended - spread.started) * (spread.seq::numeric / (spread.total + 1))
from
  spread
where
  spread.id = e.id;

update crm.opportunity_events e
set
  actor_id = coalesce(r.user_id, o.user_id)
from
  crm.opportunities o
  left join crm.sales_reps r on r.id = o.owner_id
where
  o.id = e.opportunity_id
  and e.actor_id is null;

----------------------------------------------------------------
-- Run the nightly maintenance once
--
-- This is the function a pg_cron job would call: it re-ages
-- days_in_stage on open deals and raises is_overdue on tasks whose
-- due date has passed. Running it here proves the seeded state is
-- exactly what the scheduled job would produce.
----------------------------------------------------------------
select
  crm.refresh_deal_ages () as rows_aged;

----------------------------------------------------------------
-- Populate the materialized view report's data. (This is the DATA
-- refresh — the CATALOG refresh, supasheet.refresh_metadata(), runs
-- at the end of the schema file and is not needed again here.)
----------------------------------------------------------------
refresh materialized view crm.revenue_rollup;
